const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=0)=>hasNumber(v)?v.toLocaleString('ja-JP',{maximumFractionDigits:d}):'未確認',stamp=t=>t?new Date(t).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',hour12:false}):'未記録';
let db,store,ready=false,blocked=false,mode='work',planId=null,page='home',query='',layout='cards',filter=null,month=day().slice(0,7),selectedDate=null,edit=null,importDraft=null,restoreDraft=null,templateInfo=[],recoveryState=null;
let music={version:1,settings:musicDefaults(),tracks:[]},player=null,musicBusy=false,audioIds=new Set();
const PAGES=[['home','⌂','法人本部'],['tasks','◈','立上げ準備'],['people','♙','人材・体制'],['sites','⌖','事業場'],['equipment','▤','測定器・保護具'],['inspections','◷','点検・対応'],['plans','⇄','計画比較'],['imports','▧','資料・取込']];
const dataset=()=>mode==='work'?store.work:mode==='demo'?store.demo:mode==='legacy'?store.legacySamples:store.plans.find(p=>p.id===planId);
const asOf=()=>mode==='plan'&&dataset()?dataset().asOf:day();
