const siteName=r=>dataset()?.sites.find(s=>s.id===r.siteId)?.name||r.name||r.siteExternalId||'事業場未設定';
const tone=s=>['期限切れ','未対応','否'].includes(s)?'red':['未着手','確認待ち','保留','準備中','要確認','未確認','経過観察'].includes(s)?'amber':['完了','使用可','承認済'].includes(s)?'':'gray';
const pill=(label,cls=tone(label))=>`<span class="pill ${cls}">${esc(label||'未入力')}</span>`;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function modal(title,html){$('#dialog').classList.remove('gm-dlg');$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=`<div class="modal-body">${html}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function failure(error){toast(error?.message||'処理を完了できませんでした。');const el=$('#modal-error');if(el){el.textContent=error.message;el.hidden=false;}}
function clone(){return structuredClone(store);}
function getData(s=store){return mode==='work'?s.work:mode==='demo'?s.demo:mode==='legacy'?s.legacySamples:s.plans.find(p=>p.id===planId);}
async function persist(next,files=[]){if(blocked||!db)throw Error('保存領域が利用できません。保存は行っていません。');assignBoardNos(next.work);if(next.demo)assignBoardNos(next.demo);await saveState(db,next,files);store=next;$('#save-status').textContent=`このブラウザに保存 / ${stamp(new Date())}`;if(!document.querySelector('#solvia-visit'))render();}
async function changeData(fn,event,note=''){const next=clone(),d=getData(next);if(!d)throw Error('データ領域を選択してください。');fn(d);d.audit.unshift({at:new Date().toISOString(),event,note});await persist(next);}
let screenStack=[];
function go(next,kind=null,flt=null){if(!NAV_PAGES.includes(next))screenStack.push({page,query,filter,selectedDate,scroll:$('#page').scrollTop});else screenStack=[];if($('#dialog').open)$('#dialog').close();page=next;query='';filter=flt;selectedDate=null;render();$('#page').scrollTop=0;}
function backScreen(){const prev=screenStack.pop();if(!prev){go('home');return;}({page,query,filter,selectedDate}=prev);render();$('#page').scrollTop=prev.scroll;}
function safeLink(url,label){try{const u=new URL(url);if(['http:','https:'].includes(u.protocol))return `<a href="${esc(u.href)}" target="_blank" rel="noopener">${esc(label||url)} ↗</a>`;}catch{}return esc(label||url||'未入力');}
function known(a,unit=''){return a.total===0?'対象なし':`${fmt(a.value,1)}${a.value===null?'':unit} <small>採用 ${a.known}/${a.total}件${a.complete?'':'・不足あり'}</small>`;}
function proofStatus(r,key){return verified(r,key)?pill('確認記録あり'):pill('根拠・確認日・確認先が未確認','amber');}
function sourceNote(r){if(!r.source)return '<div class="source-note">アプリで登録 / 不変ID：'+esc(r.id)+'</div>';const meta=dataset().imports.find(f=>f.id===r.source.fileId);return `<div class="source-note">元資料：${esc(meta?.name||'原本')} / ${esc(r.source.sheet)} ${r.source.row}行<br>不変ID：${esc(r.id)}<br>元資料の記載と実務の確認結果は区別して管理します。 <button data-original="${esc(r.source.fileId)}">原本を取得</button>${r.imported?`<details><summary>元行の記載値を確認</summary><pre>${esc(JSON.stringify(r.imported,null,2))}</pre></details>`:''}</div>`;}
function listRows(type){const d=dataset();if(!d)return [];return d[type].filter(r=>{if(query&&!JSON.stringify(r).toLowerCase().includes(query.toLowerCase()))return false;if(filter?.type===type&&filter.statuses&&!filter.statuses.includes(r.status))return false;if(filter?.type===type&&filter.id&&r.id!==filter.id)return false;if(filter?.type===type&&filter.key&&r[filter.key]!==filter.value)return false;return true;});}
function render(){if(!ready)return;beforeRender();unmountWorld();const activeNav=page==='map'?'map':['inspections','visit','record','route','bess','incidents'].includes(page)?'inspections':['others','settings','imports','documents','references','plans','history','calendar'].includes(page)?'others':'home';$('#nav').innerHTML=[['home','本部','office'],['map','地図','map'],['inspections','点検','clipboard'],['others','メニュー','gear']].map(([id,label,icon])=>`<button data-page="${id}" class="${activeNav===id?'active':''}" ${activeNav===id?'aria-current="page"':''}><span class="nav-pixel">${pixel(icon)}</span>${label}</button>`).join('');$('#page-title').textContent=PAGES.find(p=>p[0]===page)?.[2]||TYPES[page]||({'prep-tree':'立上げ準備の管理表',route:'点検する日の計画',attention:'要対応・未確認',history:'準備と配置の履歴',next:'次の準備',others:'メニュー',settings:'設定',map:'地図',calendar:'共通カレンダー'})[page]||'法人運営';$('#page-subtitle').textContent=page==='home'?'人材と拠点を整え、次の一手を決める。':'記載値と確認済みの情報を分けて管理する。';if(store.legacySamples&&!$('#mode option[value=legacy]'))$('#mode').insertAdjacentHTML('beforeend','<option value="legacy">引継ぎサンプル</option>');$('#mode').value=mode;const d=dataset();document.body.dataset.page=page;$('#back-screen').hidden=NAV_PAGES.includes(page);$('#mode-band').hidden=page!=='plans';
 $('#mode-band').innerHTML=`<div class="mode-band ${mode}"><div><b>${mode==='work'?'実務モード':mode==='demo'?'独立デモ・すべて架空':'計画モード・仮条件'}</b><small>${mode==='work'?'元資料の取込みと本人の確認記録を管理。地図・点検と同じ台帳を使用します。':mode==='demo'?'この領域の編集は実務・計画へ反映されません。':'実務のコピーを編集。元の実務記録は変更しません。'} ${mode==='plan'&&d?'作成：'+esc(stamp(d.createdAt)):''}</small></div><div>${mode==='plan'?`<select id="plan-select" aria-label="計画を選ぶ"><option value="">計画を選択</option>${store.plans.map(p=>`<option value="${esc(p.id)}" ${p.id===planId?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${d?`<label>計画上の基準日 <input id="plan-date" type="date" value="${esc(d.asOf)}"></label><button id="plan-advance">7日進める</button>`:''}`:`<span>基準日 ${day()} JST</span>`}<button data-new-plan>＋ 計画を作る</button></div></div>`;
 const target=$('#page');if(target.contains($('#mode-band')))target.before($('#mode-band'));if(!d&&!['plans','imports','others','settings','map'].includes(page)){target.innerHTML=emptyArea();return;}
 if(page==='home')target.innerHTML=integratedHome(d);else if(page==='monitor')target.innerHTML=integratedMonitor(d);else if(page==='visit')target.innerHTML=inspectionScreen(d);else if(page==='record')target.innerHTML=recordPage(d);else if(page==='prep-tree')target.innerHTML=d?prepTreeHtml(d.tasks,asOf()):emptyArea();else if(page==='route')target.innerHTML=routePage(d);else if(page==='calendar')target.innerHTML=integratedCalendar(d);else if(page==='others')target.innerHTML=othersHtml();else if(page==='settings')target.innerHTML=settingsHtml();else if(page==='map')target.innerHTML=integratedMap(d);else if(page==='plans'){target.innerHTML=plansHtml();target.prepend($('#mode-band'));}else if(page==='imports')target.innerHTML=importsHtml();else if(page==='next')target.innerHTML=nextTasksHtml(d);else if(page==='attention')target.innerHTML=attentionHtml(d);else if(page==='history')target.innerHTML=`<section class="panel body-pad">${d.audit.map(a=>`<div class="audit-row">${esc(a.event)} ／ ${esc(a.note)}<small>${stamp(a.at)}</small></div>`).join('')||'<p>まだ履歴はありません。</p>'}</section>`;else if(page==='inspections')target.innerHTML=integratedInspections(d);else target.innerHTML=entitiesHtml(page);{const gp=GAME_PAGES.includes(page);document.body.classList.toggle('gm-page',gp||['tasks','people','prep-tree'].includes(page));if(gp&&page==='calendar'){const h=target.querySelector('.calendar-head');if(h&&!h.querySelector('[data-page-back]'))h.insertAdjacentHTML('beforeend','<button type="button" class="gclose" data-page-back aria-label="閉じて戻る">×<small>戻る</small></button>');}else if(gp&&!target.querySelector('.gm-pagehead')){const t=$('#page-title').textContent||'';target.insertAdjacentHTML('afterbegin',`<div class="gm gm-pagehead"><section class="gw"><div class="gt">${esc(t)}${page==='settings'?`<small>${esc(mode==='work'?'実務':mode==='demo'?'独立デモ':'計画')}</small>`:`<label class="gm-mode"><span>データ領域</span><select id="mode-switch" aria-label="データ領域"><option value="work" ${mode==='work'?'selected':''}>実務</option><option value="plan" ${mode==='plan'?'selected':''}>計画</option><option value="demo" ${mode==='demo'?'selected':''}>独立デモ</option>${store.legacySamples?`<option value="legacy" ${mode==='legacy'?'selected':''}>引継ぎサンプル</option>`:''}</select></label>`}<button type="button" class="gclose" data-page-back aria-label="閉じて戻る">×<small>戻る</small></button></div></section></div>`);}}afterRender();updateMusicUi();
}
function emptyArea(){return `<section class="panel"><div class="empty">${mode==='plan'?'実務データをコピーして計画を作成してください。':'独立した架空データで操作を試せます。'}<div class="actions"><button class="primary" ${mode==='plan'?'data-new-plan':'id="start-demo"'}>${mode==='plan'?'計画を作る':'独立デモを用意'}</button></div></div></section>`;}
function card(label,value,note,page,cls=''){return `<button class="stat ${cls}" data-page="${page}"><span>${label}</span><strong>${value}</strong><small>${note}</small></button>`;}
const pixel=(name,cls='',alt='')=>`<img class="pixel ${cls}" src="pixels/${name}.svg" alt="${esc(alt)}" draggable="false">`;
function shelfItems(d){return [['meter',/絶縁抵抗/],['relay',/継電|リレー/],['gloves',/手袋|保護具|防護具/]].flatMap(([kind,pattern])=>{const e=d.equipment.find(e=>pattern.test(e.name));return e?[e]:[];});}
const gearPixel=e=>/手袋|長靴|ヘルメット|保護具|防護具/.test(e.name)?'gloves':/継電|リレー|試験/.test(e.name)?'relay':'meter';
const artSprite=(kind,extra='')=>`<span class="art-sprite sprite-${kind} ${extra}" aria-hidden="true"></span>`;
const NAV_PAGES=['home','map','inspections','others'];
// ゲーム風の作り（上の帯を出さず、題名の窓と「× 戻る」）にする画面
const GAME_PAGES=['calendar','equipment','sites','settings','imports','documents','references','plans','history','attention','next','bess','incidents','monitor','others'];

const entryIcon=type=>type==='people'?artSprite('worker','gateway-person'):type==='equipment'?artSprite('meter','gateway-meter'):pixel(type==='sites'?'office':'clipboard','gateway-icon');
function homeHtml(d){const h=homeSummary(d,asOf(),missingInfo(d)),modeLabel=mode==='work'?'実務モード':mode==='demo'?'独立デモ・架空':'計画モード・仮条件';return `<div class="gateway-home"><section class="gateway-hero"><div class="gateway-hero-head"><h2>ミニチュアの法人本部</h2><button data-page="others" class="gateway-mode">${modeLabel}</button></div><div class="hq-scene" data-fit="contain" aria-label="装飾のミニチュア本部"><button class="hq-art-button" id="scene-info" aria-label="本部の情景と登録データについて"><img class="hq-art" src="art/headquarters-yard.webp" alt="装飾の本部。人物の現在位置や実際の作業状況を示しません。" decoding="async"></button>${worldMarkup()}<span class="art-disclaimer">装飾の情景 ⓘ</span></div><p class="gateway-caption">風景は装飾です。実務の情報は下の入口から。</p></section><div class="gateway-entries">${[['people','人材・体制'],['sites','事業場'],['equipment','測定器・保護具'],['tasks','立上げ準備']].map(([type,name])=>`<button class="gateway-tile" data-page="${type}">${entryIcon(type)}<span>${type==='equipment'?'<span class="gateway-entry-word">測定器・</span><span class="gateway-entry-word">保護具</span>':name}</span></button>`).join('')}</div><div class="gateway-status"><button data-page="tasks"><span>準備完了</span><strong>${esc(h.progressLabel)}</strong></button><button data-page="attention"><span>要確認</span><strong>${h.reviewCount}<small>件</small></strong></button></div><p class="gateway-status-note">準備の進捗は、行政手続きの承認とは別です。</p></div>`;}
function othersHtml(){const leaf=(attrs,label,note='')=>`<li><button ${attrs}><b>${label}</b>${note?`<small>${note}</small>`:''}<i>›</i></button></li>`,branch=(key,title,note,items,open=false)=>`<details class="tree-branch" data-tree="${key}" ${open?'open':''}><summary><b>${title}</b><small>${note}</small></summary><ul class="tree-leaves">${items}</ul></details>`;
 return `<section class="panel body-pad tree-menu"><h2>メニュー</h2><p class="small-note">ページごとの入口の一覧です。押すと開きます。各画面の「≣ 一覧」では、その画面のボタンをすべて見られます。</p>
 ${branch('home','本部','法人本部と立上げの準備',leaf('data-page="home"','法人本部を開く')+leaf('data-page="calendar"','共通カレンダー','準備・講習・点検の予定')+leaf('data-page="tasks"','立上げ準備','すごろく・五重の塔')+leaf('data-page="prep-tree"','立上げ準備の管理表','法令・契約などのツリー')+leaf('data-page="people"','人材・体制','担当者ごとの点数')+leaf('data-page="sites"','事業場','台帳・型からまとめて追加')+leaf('data-page="equipment"','測定器・保護具')+leaf('data-page="attention"','要対応・未確認'))}
 ${branch('map','地図','中通りの3地域',leaf('data-page="map"','地図を開く','県北・県中・県南')+leaf('data-page="sites"','事業場の台帳'))}
 ${branch('inspections','点検','番号盤と点検の計画',leaf('data-page="inspections"','番号盤（全体監視盤）','本日・今月・通信')+leaf('data-route-open=""','点検する日の計画','1日の回り方・時刻の目安')+leaf('data-page="bess"','BESS 点検項目')+leaf('data-page="incidents"','緊急対応の記録'))}
 <details class="tree-branch" data-tree="others" open><summary><b>その他</b><small>資料・表示設定・データの保存</small></summary><div class="other-menu"><button data-weather-config><b>天気・地点・演出</b><small>代表地点・本部・接続・3地域のデモ</small></button><button data-page="monitor"><b>監視・保存値一覧</b><small>数値・取得日時・取得元・天気</small></button><button data-ai-review><b>今日のAIチェック</b><small>共通台帳を固定ルールで確認・AI未接続</small></button><button data-page="documents"><b>文書・添付資料</b><small>保存先・期限・ファイル</small></button><button data-page="calendar"><b>共通カレンダー</b><small>準備・講習・点検の予定</small></button>${vaultEntry()}<button data-page="settings"><b>設定</b><small>実務／計画／デモ・情景の動き</small></button><button data-backup><b>全体保存・バックアップ</b><small>実務・計画・原本・BGM設定を書き出す</small></button><button data-restore><b>バックアップから復元</b><small>確認後に法人運営データを復元する</small></button><button id="bgm-button"><b>BGM・音楽室</b><small data-music-status>曲を登録・選択／再生・停止／音量</small></button><button data-page="imports"><b>Excel取込・資料</b><small>原本、文書、参考資料、独立デモ</small></button><button data-page="plans"><b>計画・比較</b><small>実務のコピーで仮の受託を検討</small></button><button data-page="history"><b>準備と配置の履歴</b><small>変更した内容を確認</small></button><a href="../legacy.html"><b>旧監視詳細・報告書 ↗</b><small>引継ぎ前の旧保存領域・編集は統合台帳に同期されません</small></a></div></details></section>`;}
function settingsHtml(){return `<section class="panel body-pad"><h2>設定</h2><p>運用段階：${dataset()?.operating?"運営中":"立上げ準備中"}</p><button data-operating>本人操作で${dataset()?.operating?"準備中へ戻す":"運営開始へ切り替える"}</button><p>進捗から自動切替しません。準備記録は保持されます。</p><label class="world-preference-label">データ領域<select id="mode-switch"><option value="work" ${mode==='work'?'selected':''}>実務モード</option><option value="plan" ${mode==='plan'?'selected':''}>計画モード</option><option value="demo" ${mode==='demo'?'selected':''}>独立デモ</option>${store.legacySamples?`<option value="legacy" ${mode==='legacy'?'selected':''}>引継ぎサンプル</option>`:''}</select></label><div class="demo-sample"><b>点検項目の分け方</b><small>最重要・重要・表示しない を項目ごとに決めます。高圧向けの項目もここで表示できます（法令上の基準ではありません）。</small><div class="actions"><button data-catalog-settings>点検項目の分け方を開く</button></div></div>${mode==='demo'&&store.demo?`<div class="demo-sample"><b>見本の事業場（独立デモの中だけ）</b><small>番号盤の見た目を確かめるための架空の事業場を足します。実務の領域には入りません。今ある事業場は消しません。</small><div class="actions"><button id="reset-demo">独立デモを作り直す（見本5拠点）</button><button data-demo-sample="50">見本50拠点を入れる</button><button data-demo-sample="100">見本100拠点を入れる</button></div></div>`:''}<label class="world-preference-label">情景の動き<select id="world-preference"><option value="auto" ${getWorldPreference()==='auto'?'selected':''}>端末の設定に合わせる</option><option value="quiet" ${getWorldPreference()==='quiet'?'selected':''}>控えめに動かす</option><option value="off" ${getWorldPreference()==='off'?'selected':''}>動きを止める</option></select></label><div class="actions"><button id="bgm-button">BGMの選曲・音量・オン／オフ</button><button id="notices">原資料の注意書き</button></div><p class="small-note">${esc($('#save-status').textContent)}<br>このブラウザに保存。自動同期・自動バックアップは未実装です。</p></section>`;}
function mapHtml(){return `<section class="panel body-pad"><span class="pill amber">未実装</span><h2 style="margin-top:12px">法人運営の地図</h2><p>この台帳の事業場を地図へ配置する機能は、まだ実装していません。住所から正確な位置を作ったり、未登録の拠点を表示したりしません。</p><div class="actions"><button data-page="sites" class="primary">事業場の所在地を確認</button></div><p class="small-note">既存の現場管理アプリの地図は引継ぎ前のデータです。</p><a class="external-map" href="../">別データの現場管理を開く ↗</a></section>`;}
function orderedTasks(d){return d.tasks.filter(t=>t.status!=='完了'&&!(t.status==='不要'&&t.unnecessaryReason?.trim())).sort((a,b)=>Number(!!b.due&&b.due<asOf())-Number(!!a.due&&a.due<asOf())||({高:0,中:1,低:2}[a.priority]??3)-({高:0,中:1,低:2}[b.priority]??3)||(a.due||'9999').localeCompare(b.due||'9999')||Number(!!dependencyProblems(d,a).length)-Number(!!dependencyProblems(d,b).length)||(a.no||0)-(b.no||0));}
function nextTasksHtml(d){const rows=orderedTasks(d);return `<section class="panel"><div class="panel-head"><h2>次に整える準備</h2></div><p class="body-pad small-note">期限超過 → 本人設定の優先度 → 期限 → 前提条件 → No.の順。未設定の条件は自動確定しません。</p>${rows.map(t=>`<button class="prep-row" data-edit="tasks:${t.id}"><span><strong>${esc(t.name)}</strong><small>${esc(t.due||'期限未設定')} ／ 優先度 ${esc(t.priority||'未設定')}<br>${dependencyProblems(d,t).length?'先に必要：'+esc(dependencyProblems(d,t).join('、')):'設定済みの前提条件に未完了なし（未設定条件は含まない）'}</small></span><b>›</b></button>`).join('')||'<div class="empty-row">対象なし。完了は業務開始可の判定ではありません。</div>'}</section>`;}
function attentionHtml(d){const h=homeSummary(d,asOf(),missingInfo(d));return `<section class="panel"><div class="panel-head"><h2>要確認 ${h.reviewCount}件</h2></div><p class="body-pad small-note">入力不足、体制・機器の確認事項、期限超過、未解決対応を表示します。異常の現場数や承認の可否を判定する数値ではありません。</p><div class="notification-list body-pad">${h.reviews.map(x=>`<button ${x.page?`data-page="${x.page}"`:`data-open="${x.type}:${x.id}"`}>${esc(x.text)} ›</button>`).join('')||'<p>入力済みの範囲で確認事項なし。未登録の条件までは判定できません。</p>'}</div></section>`;}
function settingsForm(){go('others');}
function missingInfo(d){const s=summary(d,asOf()),rows=[];for(const r of workloadSites(d)){if(!verified(r,'points'))rows.push({type:'sites',id:r.id,text:`${r.name}：換算点数または確認根拠が不足`});if(!d.people.some(p=>p.id===r.assigneeId))rows.push({type:'sites',id:r.id,text:`${r.name}：担当者が未配置`});if(!d.people.some(p=>p.id===r.deputyId)||r.deputyId===r.assigneeId)rows.push({type:'sites',id:r.id,text:`${r.name}：代務体制を確認`});if(!hasNumber(r.monthlyFee))rows.push({type:'sites',id:r.id,text:`${r.name}：契約料未入力`});if(!d.inspections.some(i=>i.siteId===r.id))rows.push({type:'sites',id:r.id,text:`${r.name}：点検予定・必要機器の割当未設定（充足は判断保留）`});if(!['workHours','travelHours','visitsPerMonth'].every(k=>hasNumber(r[k])))rows.push({type:'sites',id:r.id,text:`${r.name}：社内計画用の件数・作業／移動時間が不足`});if(r.approval!=='受理・承認済')rows.push({type:'sites',id:r.id,text:`${r.name}：事業場ごとの外部委託承認は記録上未完了`});}
 for(const p of d.people){const l=personLoad(d,p);if(!verified(p,'capacity'))rows.push({type:'people',id:p.id,text:`${p.name}：担当可能点数の確認根拠が不足`});if(l.margin!==null&&l.margin<0)rows.push({type:'people',id:p.id,text:`${p.name}：確認済み点数が担当可能点数を${-l.margin}超過`});if(!hasNumber(p.monthlyHours))rows.push({type:'people',id:p.id,text:`${p.name}：月間稼働可能時間が未入力`});}
 for(const t of d.tasks){const deps=dependencyProblems(d,t);if(deps.length)rows.push({type:'tasks',id:t.id,text:`${t.name}：先に必要な準備 ${deps.join('、')}`});if(t.status==='不要'&&!t.unnecessaryReason?.trim())rows.push({type:'tasks',id:t.id,text:`${t.name}：不要理由が未記録（分母から除外しません）`});}
 for(const w of s.equipmentWarnings)rows.push({type:'inspections',id:w.inspectionId,text:w.text});for(const i of d.inspections)if(!(i.equipmentIds||[]).length)rows.push({type:'inspections',id:i.id,text:`${siteName(i)}：必要機器の割当未設定（機器充足は判断保留）`});for(const e of d.equipment){const x=inventoryState(e,asOf());if(e.necessity!=='不要'&&(!x.ready||e.due&&e.due<asOf()))rows.push({type:'equipment',id:e.id,text:`${e.name}：${x.reason}`});}return rows;}
function entityStatus(type,r){if(type==='people')return r.fullTime||'常勤未確認';if(type==='equipment')return inventoryState(r,asOf()).reason;if(type==='bess')return r.result||'未記録';if(type==='incidents')return r.restoredAt&&r.permanent?'恒久対策記載あり':'対応待ち';return r.status||r.reportStatus||r.priority||'未入力';}
function entityCard(type,r){const d=dataset();let data='',foot='';if(type==='people'){const l=personLoad(d,r);data=`<div><span>担当可能点数・確認済</span><b>${fmt(l.capacity,1)}</b></div><div><span>配置からの点数・確認済分</span><b>${fmt(l.points.value,1)}</b></div><div><span>担当余力</span><b>${fmt(l.margin,1)}</b></div><div><span>担当現場</span><b>${l.sites.length}</b></div>`;foot=`免状：${esc(r.license||'未入力')} / 実務経験 ${fmt(r.experience,1)}年<br>得意分野（自己申告）：${esc(r.skills||'未入力')}<br>記載された現在点数：${fmt(r.currentPoints,1)}（配置集計とは別）`;}else if(type==='sites'){data=`<div><span>換算点数・記載値</span><b>${fmt(r.points,1)}</b></div><div><span>月額契約料</span><b>${fmt(r.monthlyFee)}<small>円</small></b></div><div><span>担当者</span><b style="font-size:13px">${esc(personName(r.assigneeId))}</b></div><div><span>代務者</span><b style="font-size:13px">${esc(personName(r.deputyId))}</b></div>`;foot=`${esc(r.address||'所在地未入力')}<br>${esc(r.equipmentType||'設備種別未入力')} / PV ${fmt(r.pv,1)} kW / 蓄電 ${fmt(r.batteryCapacity,1)} kWh<br>${verified(r,'points')?'点数の確認記録あり':'点数の根拠・確認日・確認先が未確認'}`;}else if(type==='equipment'){data=`<div><span>数量</span><b>${fmt(r.quantity)}</b></div><div><span>次回期限</span><b style="font-size:13px">${esc(r.due||'未入力')}</b></div>`;foot=`${esc(r.ownership||'所有区分未入力')} / ${esc(r.location||'保管場所未入力')}<br>予備器：${esc(r.spare||'未入力')}`;}return `<button class="entity-card" data-open="${type}:${r.id}"><div class="card-top"><span>${esc(r.externalId||r.role||r.category||r.id.slice(0,8))}</span>${pill(entityStatus(type,r))}</div><h3>${esc(r.name||r.event||r.kind||'未入力')}</h3>${data?`<div class="data-grid">${data}</div>`:''}<div class="card-foot">${foot||esc(r.deliverable||r.memo||r.contents||'詳細を確認')}</div></button>`;}
function bulkSitesForm(tid=''){const d=dataset();if(!d){toast('データ領域を選択してください');return;}const list=templatesOf(d),t=list.find(x=>x.id===tid)||list[0],v={...t.values};
 modal('型からまとめて追加',`<div id="modal-error" class="modal-error" role="alert" hidden></div><form id="site-bulk"><p class="small-note">追加先：<b>${esc(modeLabel())}</b>。同じ構成の事業場を1〜100件まとめて作ります。番号盤の番号は自動で付きます。確認の記録（根拠・確認日）は写さないので、各事業場で確認してください。</p>
 <div class="form-grid"><label class="form-field">型<select name="template" data-site-bulk-template>${list.map(x=>`<option value="${esc(x.id)}" ${x.id===t.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>
 <label class="form-field">件数<input name="count" type="number" min="1" max="100" step="1" inputmode="numeric" required value="10"></label>
 <label class="form-field">名前の頭<input name="prefix" required maxlength="80" value="${esc(t.name)}-"></label>
 <label class="form-field">開始番号<input name="start" type="number" min="0" step="1" inputmode="numeric" value="${d.sites.length+1}"></label>
 <label class="form-field">状態<select name="status">${BULK_STATUSES.map(x=>`<option ${x===(mode==='plan'?'受託予定':'候補')?'selected':''}>${x}</option>`).join('')}</select></label>
 <label class="form-field">担当者<select name="assigneeId"><option value="">未選択</option>${d.people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>
 ${TEMPLATE_KEYS.map(k=>inputField('sites',SCHEMA.sites.find(f=>f.key===k),v)).join('')}</div>
 <p class="small-note" data-site-bulk-preview>名前の例：${esc(bulkName(t.name+'-',d.sites.length+1))} 〜</p>
 <section class="proof-block"><label><input type="checkbox" name="saveTemplate"> この内容を型として保存する</label><label class="form-field">型の名前<input name="templateName" maxlength="80" value="${esc(t.id===STARTER_ID?'':t.name)}" placeholder="例：低圧PV＋蓄電池 50kW"></label></section>
 <div class="form-footer"><button class="primary" type="submit">まとめて追加</button></div></form>`);}
const STARTER_ID='starter-lv-bess',modeLabel=()=>mode==='work'?'実務モード':mode==='demo'?'独立デモ・架空':'計画モード・仮条件';
async function saveBulkSites(form){const f=new FormData(form),num=k=>{const raw=String(f.get(k)||'').trim();return raw===''?null:Number(raw);},values={};
 for(const k of TEMPLATE_KEYS){const fd=SCHEMA.sites.find(x=>x.key===k);if(fd.type==='number'){const n=num(k);if(n!==null&&(!Number.isFinite(n)||n<0))throw Error(fd.label+'は0以上の数値で入力してください。');if(n!==null)values[k]=n;}else{const x=String(f.get(k)||'').trim();if(x)values[k]=x;}}
 const opts={count:num('count'),start:num('start')??1,prefix:String(f.get('prefix')||''),status:String(f.get('status')||''),assigneeId:String(f.get('assigneeId')||''),values};let made=[];
 await changeData(d=>{made=bulkSites(d,opts);if(f.get('saveTemplate'))saveTemplate(d,f.get('templateName'),values);},'事業場をまとめて追加',`${opts.count}件`);
 $('#dialog').close();render();toast(`事業場を${made.length}件追加しました（${made[0]?.name} 〜 ${made.at(-1)?.name}）`);}
function pointsPanel(d){const p=pointsByPerson(d),n=v=>v===null?'未入力':fmt(v,2),miss=t=>t.missing?`<small class="amber">点数未入力 ${t.missing}か所</small>`:'';
 const row=(name,t,cap='',note='')=>`<tr><th scope="row">${name}</th><td>${t.sites}<small>受託中 ${t.active}・予定 ${t.planned}</small></td><td><b>${t.sites?n(t.points):'0'}</b>${miss(t)}<small>確認済み ${n(t.confirmed)}（${t.confirmedSites}か所）</small></td><td>${cap}${note}</td></tr>`;
 return `<section class="panel body-pad points-panel" id="points-panel"><h3>担当者ごとの点数</h3><p class="small-note">受託中・受託予定・申請中の事業場の「換算点数・記載値」を担当者ごとに足した数です。上限を超えるかどうかの判定はしません。担当可能点数は本人が入れた記載値です。</p><div class="table-wrap"><table><thead><tr><th>担当者</th><th>事業場</th><th>点数の合計</th><th>担当可能点数（記載値）</th></tr></thead><tbody>${p.rows.map(r=>row(esc(r.name),r,r.capacity===null?'未入力':fmt(r.capacity,2),`<small>${r.capacityConfirmed?'確認記録あり':'根拠等未確認'}</small>${r.over?'<small class="amber">合計が記載値より多い</small>':''}`)).join('')}${p.unassigned.sites?row('担当者なし',p.unassigned,'—'):''}${row('合計',p.total,'—')}</tbody></table></div></section>`;}
function entitiesHtml(type){const rows=listRows(type),d=dataset(),special=['people','sites','equipment'].includes(type),columns=type==='tasks'?['no','name','owner','due','status']:type==='people'?['name','role','capacity','assignee','monthlyHours']:type==='sites'?['name','status','assigneeId','deputyId','points','monthlyFee']:type==='equipment'?['name','quantity','ownership','due','status']:type==='incidents'?['name','occurredAt','event','restoredAt','permanent']:type==='bess'?['no','name','procedure','result']:type==='documents'?['name','revision','status','due','location']:['name','priority','purpose','reviewedOn'];return `${type==='people'?rosterHtml(d):''}${type==='tasks'?sugorokuHtml(d.tasks,asOf())+'<div class="actions" style="margin:0 0 10px"><button data-page="prep-tree">区分ごとの管理表（ツリー） ›</button></div>':''}<div class="section-tools"><input id="search" type="search" placeholder="名称・担当・メモを検索" aria-label="検索" value="${esc(query)}">${special?`<div class="view-switch"><button data-layout="cards" class="${layout==='cards'?'active-choice':''}">カード</button><button data-layout="table" class="${layout==='table'?'active-choice':''}">一覧</button></div>`:''}${type==='equipment'?'<button data-page="imports">文書・設定</button><button data-page="inspections">点検計画</button>':''}<button class="primary" data-new="${type}">＋ ${TYPES[type]}を登録</button>${type==='sites'?'<button data-site-bulk>型からまとめて追加</button>':''}${filter?'<button id="clear-filter">絞り込み解除</button>':''}</div>${type==='tasks'?`<button data-page="next" class="primary" style="margin-bottom:12px">次の準備を優先順に確認 ›</button>${newSuggestions(d).length?`<button data-prep-suggest style="margin:0 0 12px 8px">＋ おすすめの準備項目（${newSuggestions(d).length}件）</button>`:''}<section class="panel body-pad"><h3>準備の一覧</h3><p class="small-note">完了 ${taskProgress(d).done} / 対象 ${taskProgress(d).total}・不要 ${taskProgress(d).excluded}（理由記録ありのみ除外）</p><div class="progress-track"><span style="width:${(taskProgress(d).rate||0)*100}%"></span></div><p class="small-note">依存関係は本人が設定します。原資料にない依存関係を自動で確定しません。</p></section>`:''}${type==='people'?pointsPanel(d):''}${type==='bess'?'<div class="warning">Excelの26点検項目と記載値を表示します。現場・実施日ごとに独立したBESS実績票を作る機能は次段階です。項目の達成から安全を判定しません。</div>':''}${!rows.length?'<section class="panel"><div class="empty">該当する記録はありません。空欄の台帳に架空の実績は追加していません。</div></section>':special&&layout==='cards'?`<div class="cards">${rows.map(r=>entityCard(type,r)).join('')}</div>`:`<section class="panel table-wrap"><table><thead><tr>${columns.map(k=>`<th>${esc(SCHEMA[type].find(f=>f.key===k)?.label||k==='assignee'&&'担当現場'||k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map((k,i)=>`<td>${i===0||k==='name'?`<button class="table-name" data-open="${type}:${r.id}">${esc(r[k]??'未入力')}</button>`:k==='status'||k==='result'?pill(k==='status'?entityStatus(type,r):r[k]):k==='assigneeId'||k==='deputyId'?esc(personName(r[k])):k==='assignee'?personLoad(d,r).sites.length:typeof r[k]==='number'?fmt(r[k],1):esc(r[k]||'未入力')}${k==='points'||k==='capacity'?`<small>${verified(r,k)?'確認記録あり':'根拠等未確認'}</small>`:''}${k==='name'&&type==='tasks'&&dependencyProblems(d,r).length?`<small class="amber">先行項目：${esc(dependencyProblems(d,r).join('、'))}</small>`:''}</td>`).join('')}</tr>`).join('')}</tbody></table></section>`}`;}
function fieldValue(type,r,f){if(['people','sites'].includes(f.type)){const rows=dataset()[f.type];return rows.find(x=>x.id===r[f.key])?.name||'未配置・未選択';}if(f.type==='tasks')return (r[f.key]||[]).map(id=>dataset().tasks.find(t=>t.id===id)?.name||'参照先なし').join('、')||'未設定';if(f.type==='equipment')return (r[f.key]||[]).map(id=>dataset().equipment.find(t=>t.id===id)?.name||'参照先なし').join('、')||'未設定';if(f.type==='number')return fmt(r[f.key],2);return r[f.key]||'未入力';}
function openRecord(type,id){const d=dataset(),r=d[type].find(r=>r.id===id);if(!r)return;if(type==='people'){modal(r.name||'人材',personCard(d,r,{fields:SCHEMA.people.map(f=>[f.label,fieldValue(type,r,f)]),proofs:Object.entries(r.proofs||{}).map(([key,p])=>`<p class="td-note">${esc(SCHEMA.people.find(f=>f.key===key)?.label||'資格・常勤等')}の確認記録：${p.confirmed?'本人が確認':'未確定'}・根拠 ${esc(p.basis||'未入力')}・確認日 ${esc(p.date||'未入力')}</p>`).join('')}));$('#dialog').classList.add('gm-dlg');return;}let extra='';if(type==='people'){const load=personLoad(d,r);extra=`<section class="panel body-pad"><h3>担当現場・配置</h3>${(d.visits||[]).filter(v=>v.personId===id).map(v=>`<p>${esc(v.at||'未記録')} ${esc(d.sites.find(s=>s.id===v.siteId)?.name||'参照先未登録')} / ${v.status==='complete'?'点検完了':'下書き'}</p>`).join('')}${load.sites.map(s=>`<div class="list-item"><button data-open="sites:${s.id}">${esc(s.name)}</button><button data-edit="sites:${s.id}">配置変更</button></div>`).join('')||'<p class="small-note">負荷対象の担当現場はありません。</p>'}<p>資格・常勤等の確認記録：${r.proofs?.qualification?.confirmed?'記録あり（根拠を要確認）':'未確認'}<br>自己申告の得意分野：${esc(r.skills||'未入力')}</p><p class="small-note">資格・実務要件と自己申告の得意分野は別です。能力点・人物評価は生成しません。</p></section>`;}if(type==='sites')extra=`<section class="panel body-pad"><h3>点検予定</h3>${d.inspections.filter(i=>i.siteId===id).map(i=>`<div class="list-item"><button data-open="inspections:${i.id}">${esc(i.date||'予定日未入力')} / ${esc(i.kind)}</button></div>`).join('')||'<p class="small-note">この事業場に結びつく予定は未登録です。</p>'}<p class="small-note">住所は地域分類に使用します。模式図と実座標は別管理です。</p></section>`;if(type==='tasks'){const deps=dependencyProblems(d,r);extra=`<div class="warning">${deps.length?'先に必要：'+esc(deps.join('、')):'設定済みの依存先は未完了なし。設定していない前提条件は含みません。'}<br>全項目の完了は、要件適合・外部委託承認・業務開始の可否を意味しません。</div>`;}if(type==='documents')extra=`<section class="panel body-pad"><h3>添付ファイル</h3><label>ファイルを添付<input type="file" id="document-upload" data-document="${esc(id)}"></label><p>1ファイル8MBまで。このブラウザと全体バックアップに保存します。</p>${(d.attachments||[]).filter(a=>a.documentId===id).map(a=>`<p><a href="${esc(a.data)}" download="${esc(a.name)}">${esc(a.name)} ↓</a></p>`).join('')}</section>`;if(type==='incidents')extra=`<section class="panel body-pad"><h3>対応の時系列</h3>${(r.timeline||[]).map(t=>`<div class="audit-row">${esc(t.note)}<small>${stamp(t.at)}</small></div>`).join('')||'<p>経過メモはまだありません。</p>'}<button data-timeline="${r.id}">経過を追加</button></section>`;
 if(type==='people')extra+=`<section class="panel body-pad"><h3>予定・点検履歴</h3>${(d.events||[]).filter(e=>e.personId===id).map(e=>`<p>${esc(e.date||'日程未定')} ${esc(e.title)}</p>`).join('')}${(d.visits||[]).filter(v=>v.personId===id).map(v=>`<p>${esc(v.at)} / ${esc(d.sites.find(s=>s.id===v.siteId)?.name)} / ${v.status==='complete'?'点検完了':'下書き'}</p>`).join('')||'<p>点検記録は未登録です。</p>'}</section>`;if(type==='equipment')extra+=`<section class="panel body-pad"><h3>使用記録</h3>${(d.visits||[]).filter(v=>v.equipmentIds?.includes(id)).map(v=>`<p>${esc(v.at)} / ${esc(d.sites.find(s=>s.id===v.siteId)?.name)} / ${esc(v.note)}</p>`).join('')||'<p>使用記録は未登録です。</p>'}</section>`;modal(r.name||r.event||r.kind||TYPES[type],`<div class="actions"><button class="primary" data-edit="${type}:${id}">編集する</button></div>${extra}<div class="detail-grid">${SCHEMA[type].map(f=>`<div><small>${esc(f.label)}</small>${f.key==='location'&&['documents','references'].includes(type)?safeLink(r[f.key]):esc(fieldValue(type,r,f))}</div>`).join('')}</div>${Object.entries(r.proofs||{}).map(([key,p])=>`<div class="proof-block"><h3>${esc(SCHEMA[type].find(f=>f.key===key)?.label||'資格・常勤等')} の確認記録</h3><p>${p.confirmed?'本人が確認記録を有効化':'確認記録は未確定'}<br>根拠：${esc(p.basis||'未入力')}<br>確認日：${esc(p.date||'未入力')}<br>確認先：${esc(p.authority||'未入力')}</p></div>`).join('')}${sourceNote(r)}`);
}
function inputField(type,f,r){const value=r[f.key],name=f.key;if(['tasks','equipment'].includes(f.type)){const options=dataset()[f.type].filter(x=>!(f.type==='tasks'&&x.id===r.id));return `<label class="form-field full">${esc(f.label)}<div class="check-grid">${options.map(o=>`<label><input type="checkbox" name="${name}" value="${o.id}" ${(value||[]).includes(o.id)?'checked':''}>${esc(o.name||o.kind)}</label>`).join('')||'<span>登録された候補はありません</span>'}</div></label>`;}if(['people','sites'].includes(f.type)){const options=dataset()[f.type];return `<label class="form-field">${esc(f.label)}<select name="${name}"><option value="">未選択</option>${value&&!options.some(o=>o.id===value)?`<option value="${esc(value)}" selected>参照先不明・要確認</option>`:''}${options.map(o=>`<option value="${o.id}" ${value===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`;}if(f.type==='select'){const options=[...(f.options||[])];if(value&&!options.includes(value))options.unshift(value);return `<label class="form-field">${esc(f.label)}<select name="${name}"><option value="">未入力</option>${options.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}if(f.type==='textarea')return `<label class="form-field full">${esc(f.label)}<textarea name="${name}" maxlength="5000">${esc(value)}</textarea></label>`;return `<label class="form-field">${esc(f.label)}<input name="${name}" type="${f.type}" ${f.type==='number'?'min="0" step="any"':''} ${name==='name'&&['tasks','people','sites','equipment','documents'].includes(type)?'required':''} value="${esc(value??'')}" ${f.type==='text'?'maxlength="500"':''}></label>`;}
function editRecord(type,id=null,preset={}){const old=id?dataset()[type].find(r=>r.id===id):null,r=old||record(type,preset);if(!old&&type==='tasks')r.status='未着手';if(!old&&type==='sites')r.status=mode==='plan'?'受託予定':'候補';edit={type,id:old?.id,record:r};const keys=type==='people'?['capacity','currentPoints','qualification']:type==='sites'?['points','responseMinutes']:[];
 (type==='people'?(t,h)=>{modal(t,h);$('#dialog').classList.add('gm-dlg');}:modal)((old?'編集：':'新規：')+TYPES[type],`<div id="modal-error" class="modal-error" role="alert" hidden></div><form id="entity-form"><p class="small-note">${mode==='plan'?'計画の仮条件のみを編集します。実務は変わりません。':'空欄は未入力として保存します。0を入力した場合と区別します。'}</p><div class="form-grid">${SCHEMA[type].map(f=>inputField(type,f,r)).join('')}</div>${keys.map(key=>{const p=r.proofs?.[key]||{},label=key==='qualification'?'資格・常勤・実務経験等':SCHEMA[type].find(f=>f.key===key)?.label;return `<section class="proof-block"><h3>${esc(label)} の確認記録</h3><div class="form-grid"><label class="form-field">根拠・資料名<input name="proof-${key}-basis" value="${esc(p.basis)}" maxlength="1000"></label><label class="form-field">確認日<input name="proof-${key}-date" type="date" value="${esc(p.date)}"></label><label class="form-field">確認先<input name="proof-${key}-authority" value="${esc(p.authority)}" maxlength="500"></label></div><div class="check-grid" style="margin-top:10px"><label><input type="checkbox" name="proof-${key}-reviewed">この値・根拠・確認日・確認先を本人が確認した</label></div><p class="small-note">変更した値は確認を付けない限り未確定です。未変更の既存確認記録は維持します。計画上の仮値を実際の承認・法令上の確認値として登録しないでください。</p></section>`;}).join('')}<div class="form-footer"><button type="button" id="cancel-edit">取消</button><button class="primary" type="submit">${mode==='plan'?'計画に保存':'この領域に保存'}</button></div></form>`);
}
async function saveEntity(form){const {type,id,record:r}=edit,data=new FormData(form),next=structuredClone(r),changed=[];for(const f of SCHEMA[type]){let value;if(['tasks','equipment'].includes(f.type))value=data.getAll(f.key);else if(f.type==='number'){const raw=String(data.get(f.key)||'').trim();value=raw===''?null:Number(raw);if(value!==null&&(!Number.isFinite(value)||value<0||['quantity','no','visitsPerMonth'].includes(f.key)&&!Number.isInteger(value)))throw Error(f.label+'は0以上の数値で入力してください。');}else value=String(data.get(f.key)||'').trim();if(f.type==='date'&&value&&!validDay(value))throw Error(f.label+'の日付を確認してください。');next[f.key]=value;if(JSON.stringify(value)!==JSON.stringify(r[f.key])){next.touched[f.key]=true;changed.push(f.label);}}
 if(type==='tasks'){const error=validateTask(dataset(),next);if(error)throw Error(error);}if(type==='sites'&&next.assigneeId&&next.assigneeId===next.deputyId)throw Error('担当者と代務者は別の人を選択してください。');if(type==='people'&&next.deputyId===next.id)throw Error('本人を代務者には設定できません。');
 for(const key of type==='people'?['capacity','currentPoints','qualification']:type==='sites'?['points','responseMinutes']:[]){const old=r.proofs?.[key]||{},p={basis:String(data.get(`proof-${key}-basis`)||'').trim(),date:String(data.get(`proof-${key}-date`)||''),authority:String(data.get(`proof-${key}-authority`)||'').trim()},changedProof=p.basis!==(old.basis||'')||p.date!==(old.date||'')||p.authority!==(old.authority||'')||next[key]!==r[key],reviewed=data.get(`proof-${key}-reviewed`)==='on';if(reviewed&&(!p.basis||!validDay(p.date)||!p.authority||key!=='qualification'&&!hasNumber(next[key])))throw Error('確認記録には値・根拠・確認日・確認先が必要です。');next.proofs[key]={...p,confirmed:reviewed||!changedProof&&old.confirmed===true};}
 await changeData(d=>{if(id)d[type]=d[type].map(x=>x.id===id?next:x);else d[type].push(next);},`${TYPES[type]} ${id?'更新':'登録'}`,`${next.name||next.kind||next.event||next.id} / ${changed.join('、')}`);$('#dialog').close();toast('保存しました');}
function inspectionsHtml(d){const events=d.inspections,days=monthDays(month);return `<div class="section-tools"><button class="primary" data-new="inspections">＋ 点検予定</button><button data-page="incidents">緊急対応 ${d.incidents.length}件</button><button data-page="bess">BESS 26項目・原本</button></div><section class="panel"><div class="calendar-head"><h2>${month.replace('-','年')}月</h2><div class="actions"><button data-month="-1" aria-label="前月">‹</button><button id="calendar-now">今月</button><button data-month="1" aria-label="翌月">›</button></div></div><p class="small-note" style="padding:0 16px">予定・実施・報告・是正は別管理。日付を進めても完了しません。</p><div class="calendar-grid">${['日','月','火','水','木','金','土'].map(x=>`<span>${x}</span>`).join('')}${days.map(x=>{const rows=events.filter(i=>i.date===x.day);return `<button data-day="${x.day}" class="calendar-day ${x.inMonth?'':'out'} ${x.day===asOf()?'today':''}">${x.number}${rows.length?`<small>${rows.length}件</small>${rows.slice(0,1).map(i=>`<small>${esc(siteName(i))}</small>`).join('')}`:''}</button>`;}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>${selectedDate?selectedDate+' の予定':'全予定'}</h2>${selectedDate?'<button id="all-inspections">全予定</button>':''}</div>${events.filter(i=>!selectedDate||i.date===selectedDate).map(i=>`<div class="list-item"><div><button data-open="inspections:${i.id}">${esc(siteName(i))} / ${esc(i.kind||'種別未入力')}</button><p>予定 ${esc(i.date||'未設定')} ${esc(i.start||'時刻未設定')} / 実施 ${esc(i.performedOn||'未記録')}<br>報告 ${esc(i.reportStatus||'未入力')} / 是正 ${esc(i.correctionStatus||'未入力')}</p></div><button data-edit="inspections:${i.id}">編集</button></div>`).join('')||'<div class="empty">該当する予定はありません。</div>'}</section>`;}
function planValues(d){const s=summary(d,d.asOf||asOf()),pointRaw=sumKnown(s.load,'points'),capacityRaw=sumKnown(d.people,'capacity');return {...s,pointRaw,capacityRaw,rawMargin:pointRaw.complete&&capacityRaw.complete&&s.unassigned===0?capacityRaw.value-pointRaw.value:null};}
function plansHtml(){const d=dataset(),plan=mode==='plan'?d:null;return `<section class="big-callout"><div><h2>次の受託を、仮条件で試す。</h2><p>実務をコピーして人材・事業場・装備を編集。日付を進めても実施・承認・講習修了は変えません。</p></div><button class="primary gold" data-new-plan>＋ 実務から計画を作る</button></section>${!plan?`<section class="panel"><div class="panel-head"><h2>保存した計画</h2></div>${store.plans.map(p=>`<div class="list-item"><div><button data-use-plan="${p.id}">${esc(p.name)}</button><p>作成 ${stamp(p.createdAt)} / 基準日 ${p.asOf}</p></div><button data-use-plan="${p.id}">開く</button></div>`).join('')||'<div class="empty">まだ計画はありません。実務が空でも計画を作れますが、確認できる範囲は入力に依存します。</div>'}</section>`:planComparison(plan)}`;}
function planComparison(plan){const base=planValues(plan.base),after=planValues(plan),r=(label,a,b,note='')=>`<tr><td>${label}<small>${note}</small></td><td>${a}</td><td>${b}</td></tr>`;return `<section class="panel"><div class="panel-head"><h2>${esc(plan.name)}</h2><div class="actions"><button data-new="sites" class="primary">＋ 仮の現場</button><button data-new="people">＋ 仮の人材</button><button data-new="equipment">＋ 仮の機器</button></div></div><div class="plan-caption">比較元は作成時の実務スナップショットです（${stamp(plan.createdAt)}）。最新の実務へ自動追従しません。<br>負荷対象＝受託中＋受託予定＋申請中。記載値の仮計算と確認済み点数を別々に表示。費用未登録のため利益は計算せず、契約料見込みを表示します。</div><div class="table-wrap"><table><thead><tr><th>比較項目</th><th>作成時の実務</th><th>現在の仮計画</th></tr></thead><tbody>${r('負荷対象の現場数',base.load.length,after.load.length)}${r('確認済み換算点数',known(base.points),known(after.points),'根拠・確認日・確認先がそろった記録のみ')}${r('記載点数の仮集計',known(base.pointRaw),known(after.pointRaw),'未確認の記載値を含む社内検討用。法令上の確認値ではない')}${r('確認済み担当余力',fmt(base.margin,1),fmt(after.margin,1),'全確認値と担当配置がそろうまで未確認')}${r('記載値による仮の余力',fmt(base.rawMargin,1),fmt(after.rawMargin,1),'記載値不足・未配置があれば未確認。個人別の偏りは人材画面で確認')}${r('月間点検件数（社内仮定）',known(base.visits,'件'),known(after.visits,'件'))}${r('月間作業＋往復移動時間',fmt(base.hours,1)+' 時間',fmt(after.hours,1)+' 時間',`入力済み ${after.hoursKnown}/${after.load.length}現場。未入力分は除外した小計`) }${r('月間稼働可能時間',known(base.available,'時間'),known(after.available,'時間'),'本人入力の社内計画値。法定点数とは別')}${r('担当未配置 / 代務体制不足',`${base.unassigned} / ${base.deputies}`,`${after.unassigned} / ${after.deputies}`)}${r('使用可能条件を確認できる機器',`${base.readyEquipment}/${plan.base.equipment.length}`,`${after.readyEquipment}/${plan.equipment.length}`)}${r('機器割当の注意件数',base.equipmentWarnings.length,after.equipmentWarnings.length,'必要機器未設定の予定や予定自体がない場合、充足は判断できない')}${r('月額契約料見込み',known(base.fee,'円'),known(after.fee,'円'),'未入力があれば記載分の小計。費用未登録につき利益ではない')}</tbody></table></div><div class="body-pad"><h3>現場追加後に不足・未確認の情報</h3><div class="notification-list">${missingInfo(plan).map(x=>`<button data-open="${x.type}:${x.id}">${esc(x.text)}</button>`).join('')||'<p>入力済みの範囲で不足検知なし。未登録の必要機器・法令基準までは判定できません。</p>'}</div></div></section>`;}
function importsHtml(){const d=dataset();return `<section class="panel"><div class="panel-head"><h2>Excelの取込みと原本</h2></div><div class="body-pad"><p>9シートの見出しと項目対応、追加・更新・手入力保護を確認してから取り込みます。原本は変更せず、このブラウザのIndexedDBへ保管します。</p><div class="actions"><button id="template-import" class="primary">添付テンプレートを確認</button><label class="upload">更新したExcelを選ぶ<input type="file" id="excel-file" accept=".xlsx"></label><button id="start-demo">独立デモで試す</button></div><p class="small-note">実務の空欄を架空の実績で補いません。人材・現場の配置は取込後に本人が選択します。名前だけの曖昧な自動配置は行いません。</p>${(d?.imports||[]).map(f=>`<div class="import-row"><strong>${esc(f.name)}</strong><small>${stamp(f.at)} / SHA-256 ${esc(f.hash)}</small><button data-original="${esc(f.id)}">原本を取得</button><details><summary>元の数式と移植した意味</summary><pre>${esc(JSON.stringify(f.formulas,null,2))}</pre></details></div>`).join('')||'<p class="small-note">この領域では未取り込みです。</p>'}</div></section><section class="panel"><div class="panel-head"><h2>文書・参照資料</h2></div><div class="body-pad actions"><button data-page="documents">文書管理 ${d?.documents.length||0}件</button><button data-page="references">参考資料 ${d?.references.length||0}件</button><button id="notices">全9シートの注意書き</button></div><p class="small-note" style="padding:0 20px 15px">参考資料の掲載内容と、最新制度を確認した結果は別欄です。資料は取り込み時点の記載であり、最新版の確認は行っていません。</p></section><section class="panel"><div class="panel-head"><h2>保存と引き継ぎ</h2></div><div class="body-pad"><p>ブラウザ内保存です。端末間同期・サーバー保存・自動バックアップは未実装。全体保存には実務・すべての計画・独立デモ・原本Excelを含めます。引継ぎ済みの現場データ・写真・予定・メモ・添付は同じ台帳のバックアップに含みます。旧保存領域は変更しません。</p><div class="actions"><button data-backup class="primary">↓ 全体をJSONで保存</button><button data-restore>↑ 全体を復元</button></div></div></section>`;}
// Excel を置けない公開先では、同じテンプレートを読み取り済みの template-parsed.json を使う（原本の保存はしない）。
async function readTemplate({needOriginal=false}={}){const response=await fetch('template.xlsx').catch(()=>null);if(response?.ok){const buffer=await response.arrayBuffer(),parsed=await parseWorkbook(buffer,'保安法人立上げ_運用テンプレート.xlsx',templateInfo);if(parsed.errors.length)throw Error(parsed.errors.join('\n'));return {buffer,parsed};}if(needOriginal)throw Error('この版では添付のExcelテンプレートを開けません。Excelファイルを選んで取り込んでください。');const fallback=await fetch('template-parsed.json').catch(()=>null);if(!fallback?.ok)throw Error('添付テンプレートを取得できません。');const parsed=await fallback.json();if(!parsed||!Array.isArray(parsed.errors)||parsed.errors.length||typeof parsed.hash!=='string')throw Error('添付テンプレートの読み取り結果が不正です。');return {buffer:null,parsed};}
async function reviewImport(buffer,name){if(!dataset())throw Error('先にデータ領域または計画を選んでください。');const parsed=await parseWorkbook(buffer,name,templateInfo),preview=previewImport(dataset(),parsed);importDraft={buffer,parsed,preview,datasetId:dataset().id};
 const count=t=>preview.actions.filter(a=>a.action===t).length;
 modal('Excelの内容と反映予定を確認',`<div id="modal-error" class="modal-error" hidden></div><h3>${esc(name)}</h3><p>対象：${mode==='work'?'実務':mode==='plan'?'選択中の計画':'独立デモ'} / 追加 ${count('add')}・更新 ${count('update')}・維持 ${count('keep')} 件</p><p class="small-note">未入力の台帳に実績は補いません。Excelにない既存行は削除しません。手入力のメモ・配置・変更値は保護し、数値が変わった確認記録は未確定に戻します。</p>${preview.errors.length?`<div class="warning red">${preview.errors.map(esc).join('<br>')}</div>`:''}<section class="panel table-wrap"><table><thead><tr><th>シート</th><th>取込対象</th><th>行数</th></tr></thead><tbody>${MAPPINGS.map(m=>`<tr><td>${m.sheet}</td><td>${TYPES[m.type]}</td><td>${parsed.records.filter(r=>r.type===m.type).length}</td></tr>`).join('')}</tbody></table></section><details><summary>全9シートの項目対応を確認</summary><div class="import-mapping">${MAPPINGS.map(m=>`<p><b>${m.sheet}</b><br>${m.keys.map((key,i)=>`${String.fromCharCode(65+i)}列 → ${SCHEMA[m.type].find(f=>f.key===key)?.label||key}`).map(esc).join('<br>')}</p>`).join('')}</div></details><details><summary>追加・更新・手入力保護の詳細（${preview.actions.length}件）</summary>${preview.actions.map(a=>`<div class="import-row"><strong>${esc(a.values.name||a.values.event||a.key)} / ${a.action==='add'?'追加':a.action==='update'?'更新':'維持'}</strong><small>${a.sheet} ${a.row}行 / ${esc(a.key)}</small>${a.changes.length?'更新：'+a.changes.map(k=>esc(SCHEMA[a.type].find(f=>f.key===k)?.label||k)).join('、'):''}${a.protectedFields.length?'<br>手入力保護：'+a.protectedFields.map(k=>esc(SCHEMA[a.type].find(f=>f.key===k)?.label||k)).join('、'):''}</div>`).join('')}</details><details><summary>元の数式7件の意味と扱い</summary><p>準備の完了・未完了・不要を除いた進捗、事業場ID件数、受託中件数、点数・契約料の合計です。アプリは行数に固定しない集計に移植し、全て不要の場合や未確認の点数は0%・正常な0として扱いません。点数と契約料は対象状態と採用件数を示します。</p><pre>${esc(JSON.stringify(parsed.formulas,null,2))}</pre></details><details><summary>注意・警告（${parsed.warnings.length}件）</summary>${parsed.warnings.map(w=>`<p>${esc(w)}</p>`).join('')||'<p>読取上の警告はありません。</p>'}</details><details><summary>原資料の注意書き</summary>${parsed.notices.map(n=>`<p><b>${n.sheet}</b><br>${esc(n.text)}</p>`).join('')}</details><label class="check-grid"><label><input id="confirm-import" type="checkbox">項目対応・件数・更新内容を確認しました。原本を保持して反映します。</label></label><div class="form-footer"><button id="apply-import" class="primary" disabled>確認して取り込む</button></div>`);
 $('#confirm-import').onchange=e=>$('#apply-import').disabled=!e.target.checked||preview.errors.length>0;
}
async function finishImport(){if(!importDraft||!$('#confirm-import')?.checked)throw Error('取り込み内容を確認してください。');if(dataset()?.id!==importDraft.datasetId)throw Error('対象領域が変わりました。もう一度内容を確認してください。');const {buffer,parsed,preview}=importDraft,meta={id:'source-'+parsed.hash,name:parsed.name,hash:parsed.hash,at:new Date().toISOString(),formulas:parsed.formulas,notices:parsed.notices},next=clone(),data=applyImport(getData(next),preview,meta);if(mode==='work')next.work=data;else if(mode==='demo')next.demo=data;else if(mode==='legacy')next.legacySamples=data;else next.plans=next.plans.map(p=>p.id===planId?data:p);await persist(next,[{id:meta.id,name:meta.name,hash:meta.hash,blob:new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}]);importDraft=null;$('#dialog').close();page='home';render();toast('原本と取り込み結果を保存しました');}
function newPlan(){modal('実務をコピーして計画を作る',`<div id="modal-error" class="modal-error" hidden></div><form id="plan-form"><p>実務の記録をコピーして作成します。以後の編集は実務を変更しません。独立デモはコピー元にしません。</p><label class="form-field">計画名<input name="name" maxlength="80" required value="次の受託計画"></label><div class="form-footer"><button class="primary" type="submit">コピーして作成</button></div></form>`);}
function notices(){const notes=dataset()?.notices.length?dataset().notices:templateInfo.map(t=>({sheet:t.name,text:t.note}));modal('元資料の注意書きと確認の区別',`<p>以下はExcelの記載です。最新の制度の確認結果ではありません。</p>${notes.map(n=>`<section class="proof-block"><h3>${esc(n.sheet)}</h3><p>${esc(n.text)}</p></section>`).join('')}<p>換算点数、担当可能点数、必要経験、点検頻度は自動確定しません。資格と自己申告の得意分野は区別します。準備完了の演出による承認・正常・業務開始の判定はありません。</p>`);}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function backup(includeAudio=false){if(!db)throw Error('保存領域にアクセスできません。');const data=await makeBackup(db,recoveryState||store,includeAudio);download(new Blob([JSON.stringify(data)],{type:'application/json'}),`solvia-corporate-${day()}.json`);$('#dialog').close();toast('全データと原本をJSONで書き出しました');}
function restoreForm(){restoreDraft=null;modal('法人運営のバックアップを復元',`<div id="modal-error" class="modal-error" hidden></div><p>実務・すべての計画・デモ・原本を置き換えます。先に「全体保存」でバックアップしてください。現場管理アプリのデータは変更しません。</p><label class="upload">バックアップJSONを選ぶ<input id="backup-file" type="file" accept=".json,application/json"></label><div id="restore-preview"></div>`);}
let busy=false;
async function act(fn,button){if(busy)return;busy=true;if(button)button.disabled=true;try{await fn();}catch(e){failure(e);}finally{busy=false;if(button?.isConnected)button.disabled=false;}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled||['bgm-button','music-play'].includes(b.id))return;const open=b.dataset.open,editing=b.dataset.edit;
 if(b.hasAttribute('data-page-back')){backScreen();return;}if(b.hasAttribute('data-site-bulk')){bulkSitesForm();return;}if(b.hasAttribute('data-prep-suggest')){const list=newSuggestions(dataset());modal('おすすめの準備項目',`<form id="prep-suggest"><p class="small-note">Excel（予測）に足りなさそうな準備の候補です。法令上の要否は決めていません。確認先に確かめてください。選んだものだけ「未着手」で足します。今ある項目は消しません。</p>${list.map((t,i)=>`<label class="prep-sg"><input type="checkbox" name="pick" value="${i}" checked><span><b>${esc(t.category)}：${esc(t.name)}</b><small>${esc(t.deliverable)}</small><small>確認先：${esc(t.authority)}</small></span></label>`).join('')}<div class="form-footer"><button class="primary" type="submit">選んだ項目を足す</button></div></form>`);return;}if(b.id==='settings-button'){settingsForm();return;}if(b.id==='back-screen'){backScreen();return;}if(b.id==='scene-info'){modal('情景と登録データ',`<p>本部の事務所・車両・人物・太陽光・蓄電池は、独自に制作した装飾イラストです。歩行・停車・設備の動きは装飾であり、保有設備・実際の運転・点検実施・安全の状態を表しません。動きを止めても管理データは変わりません。実際の件数・氏名・担当状況は、その下の操作できる概要欄に表示しています。</p><button id="notices">原資料の注意書き</button>`);return;}if(b.id==='close-dialog'||b.id==='cancel-edit'){$('#dialog').close();return;}if(b.dataset.page){go(b.dataset.page,null,b.dataset.siteStatus?{type:'sites',statuses:b.dataset.siteStatus==='active'?['受託中']:['受託予定','申請中']}:null);return;}if(open){const [type,id]=open.split(':');openRecord(type,id);return;}if(editing){const [type,id]=editing.split(':');editRecord(type,id);return;}if(b.dataset.new){if(!dataset()){toast('データ領域を選択してください');return;}editRecord(b.dataset.new);return;}if(b.dataset.layout){layout=b.dataset.layout;render();return;}if(b.id==='clear-filter'){filter=null;render();return;}if(b.id==='notices'){notices();return;}if(b.dataset.newPlan!==undefined){newPlan();return;}if(b.dataset.usePlan){mode='plan';planId=b.dataset.usePlan;page='plans';render();return;}if(b.dataset.month){month=shiftMonth(month,Number(b.dataset.month));selectedDate=null;render();return;}if(b.id==='calendar-now'){month=asOf().slice(0,7);selectedDate=null;render();return;}if(b.dataset.day){selectedDate=b.dataset.day;render();return;}if(b.id==='all-inspections'){selectedDate=null;render();return;}if(b.dataset.timeline){modal('経過を追加',`<div id="modal-error" class="modal-error" hidden></div><form id="timeline-form" data-id="${b.dataset.timeline}"><label class="form-field">対応経過・日時は保存時に記録<textarea name="note" maxlength="3000" required></textarea></label><div class="form-footer"><button class="primary" type="submit">経過を保存</button></div></form>`);return;}
 if(!['template-import','apply-import','start-demo','reset-demo','reset-demo-yes','backup','download-backup','restore','plan-advance','confirm-restore'].includes(b.id)&&b.dataset.original===undefined&&b.dataset.backup===undefined&&b.dataset.restore===undefined)return;
 await act(async()=>{
 if(b.id==='template-import'){const {buffer,parsed}=await readTemplate({needOriginal:true});await reviewImport(buffer,parsed.name);}
 else if(b.id==='apply-import')await finishImport();
 else if(b.id==='reset-demo'){modal('独立デモを作り直しますか？',`<div class="td gm"><section class="gw"><p class="td-note" style="font-size:.84rem;color:#fff;line-height:1.6">独立デモの中の記録は、すべて新しい見本（5拠点）に置き換わります。<br>実務・計画のデータには触れません。</p></section><section class="gw gcmds" style="grid-template-columns:1fr"><button type="button" class="gc gc-main" id="reset-demo-yes">はい、作り直す</button><button type="button" class="gc" id="cancel-edit">やめる</button></section></div>`);}
 else if(b.id==='start-demo'||b.id==='reset-demo-yes'){const {buffer,parsed}=await readTemplate(),meta={id:'source-'+parsed.hash,name:parsed.name,hash:parsed.hash,at:new Date().toISOString(),formulas:parsed.formulas,notices:parsed.notices},base=emptyData('demo'),prepared=applyImport(base,previewImport(base,parsed),meta),next=clone();if(next.demo&&b.id!=='reset-demo-yes'){mode='demo';page='home';render();toast(next.demo.demoVersion>=2?'保存済みの独立デモを開きました':'保存済みの独立デモを開きました（古い見本です。本部の「独立デモ」の札から新しい見本に作り直せます）');return;}next.demo=makeDemo(prepared);await persist(next,buffer?[{id:meta.id,name:meta.name,hash:meta.hash,blob:new Blob([buffer])}]:[]);mode='demo';page='home';render();if($('#dialog').open)$('#dialog').close();toast(b.id==='reset-demo-yes'?'独立デモを新しい見本（5拠点）で作り直しました':'実務とは独立したデモを用意しました');}
 else if(b.dataset.original){const f=await original(db,b.dataset.original);if(!f)throw Error('原本がありません。原本を含むバックアップから復元してください。');download(f.blob,f.name);}
 else if(b.id==='backup'||b.dataset.backup!==undefined)backupForm();
 else if(b.id==='download-backup')await backup($('#include-audio').checked);
 else if(b.id==='restore'||b.dataset.restore!==undefined)restoreForm();
 else if(b.id==='plan-advance'){if(mode!=='plan')throw Error('計画モードだけの操作です。');await changeData(d=>{d.asOf=new Date(Date.parse(d.asOf+'T00:00:00Z')+7*86400000).toISOString().slice(0,10);},'計画日付を進める','状態は自動完了しません');}
 else if(b.id==='confirm-restore'){if(!restoreDraft||!$('#restore-check').checked)throw Error('置き換えの確認が必要です。');store=await restoreBackup(db,restoreDraft);await initMusic();recoveryState=null;blocked=false;mode='work';planId=null;$('#storage-error').hidden=true;$('#dialog').close();render();toast('全体バックアップを復元しました');}
 },b);
});
document.addEventListener('input',e=>{if(e.target.id==='search'){const start=e.target.selectionStart;query=e.target.value;render();$('#search')?.focus({preventScroll:true});$('#search')?.setSelectionRange(start,start);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='mode'||el.id==='mode-switch'){mode=el.value;if(mode==='plan'&&!store.plans.some(p=>p.id===planId))planId=store.plans[0]?.id||null;query='';filter=null;page=mode==='plan'?'plans':page;render();return;}if(el.id==='plan-select'){planId=el.value;page='plans';render();return;}if(el.id==='plan-date'){if(mode!=='plan'||!validDay(el.value)){toast('計画の日付を確認してください');return;}await act(()=>changeData(d=>d.asOf=el.value,'計画基準日を変更'));return;}
 if(el.hasAttribute('data-site-bulk-template')){bulkSitesForm(el.value);return;}if(el.id==='excel-file'){const f=el.files?.[0];if(f)await act(async()=>{if(f.size>5*1024*1024)throw Error('5MB以下のxlsxを選択してください');await reviewImport(await f.arrayBuffer(),f.name);});}
 if(el.id==='backup-file'){restoreDraft=null;const f=el.files?.[0];if(!f)return;await act(async()=>{if(f.size>180*1024*1024)throw Error('180MB以下のJSONを選択してください。');const data=JSON.parse(await f.text());if(data.format!=='solvia-corporate-backup'||!validateStore(data.state)||!Array.isArray(data.originals))throw Error('このアプリの有効な全体バックアップではありません。');restoreDraft=data;$('#restore-preview').innerHTML=`<p>実務：人材${data.state.work.people.length}・事業場${data.state.work.sites.length}・準備${data.state.work.tasks.length}件 / 計画${data.state.plans.length}件 / 原本${data.originals.length}件</p><p>BGM：${data.music?data.music.includesAudio?'音源込み（収録ファイル'+data.music.files.length+'曲）':'設定のみ・音源は別途登録が必要な場合があります':'旧形式・現在のBGM設定を維持'}</p><label class="check-grid"><label><input id="restore-check" type="checkbox">現在の法人運営データを置き換えることを確認しました</label></label><div class="form-footer"><button id="confirm-restore" class="primary" disabled>確認して全体を復元</button></div>`;$('#restore-check').onchange=e=>$('#confirm-restore').disabled=!e.target.checked;});}
});
document.addEventListener('submit',e=>{if(!['entity-form','plan-form','timeline-form','site-bulk','prep-suggest'].includes(e.target.id))return;e.preventDefault();const form=e.target;act(async()=>{if(form.id==='prep-suggest'){const list=newSuggestions(dataset()),picks=new FormData(form).getAll('pick').map(Number).map(i=>list[i]).filter(Boolean);if(!picks.length)throw Error('足す項目を選んでください');await changeData(d=>{let no=Math.max(0,...d.tasks.map(t=>Number(t.no)||0));for(const t of picks){if(d.tasks.some(x=>x.name===t.name))continue;d.tasks.push(record('tasks',{...t,no:++no,status:'未着手',memo:'Claudeの提案から追加（内容と要否は要確認）'}));}},'おすすめの準備項目を追加',picks.length+'件');$('#dialog').close();render();toast(`準備項目を${picks.length}件足しました`);return;}if(form.id==='site-bulk')await saveBulkSites(form);if(form.id==='entity-form')await saveEntity(form);if(form.id==='plan-form'){if(store.plans.length>=20)throw Error('計画は20件までです。');const name=String(new FormData(form).get('name')||'').trim();if(!name)throw Error('計画名を入力してください。');const next=clone(),plan=copyPlan(store.work,name);next.plans.push(plan);await persist(next);mode='plan';planId=plan.id;page='plans';$('#dialog').close();render();toast('実務のコピーを作成しました');}if(form.id==='timeline-form'){const note=String(new FormData(form).get('note')||'').trim();if(!note)throw Error('経過を入力してください');await changeData(d=>{const r=d.incidents.find(r=>r.id===form.dataset.id);if(!r)throw Error('対応記録がありません');r.timeline??=[];r.timeline.push({at:new Date().toISOString(),note});},'緊急対応の経過追加');$('#dialog').close();}},form.querySelector('[type="submit"]'));});
initIntegration({data:dataset,modal,go,render,toast,open:openRecord,edit:editRecord,close:()=>$('#dialog').close(),change:changeData});
document.addEventListener('click',e=>{if(e.target.closest('[data-legacy-inspections]'))modal('既存の予定・報告管理',inspectionsHtml(dataset()));});
initWorld();
try{templateInfo=await fetch('template-info.json').then(r=>{if(!r.ok)throw Error('テンプレート情報を取得できません');return r.json();});db=await openDatabase();const saved=await readState(db);if(saved){if(!validateStore(saved)){store=saved;blocked=true;throw Error('法人運営の保存データが不完全です。原データを保持して保存を停止しています。全体保存で退避し、有効なバックアップを復元してください。');}store=saved;}else{store=emptyStore();await saveState(db,store);}try{const next=clone();if(migrateUnifiedStore(next,localStorage.getItem('nakadori-desk-v1'))|(next.demo?assignBoardNos(next.demo):false)){await saveState(db,next);store=next;}}catch(e){toast(e.message);}
await initMusic();ready=true;render();$('#save-status').textContent='このブラウザに保存 / IndexedDB';}catch(e){if(!store||!validateStore(store)){recoveryState=store;store=emptyStore();}blocked=true;ready=true;$('#storage-error').hidden=false;$('#storage-error').textContent=e.message+' 仮の空データで表示しています。元の記録は上書きしていません。';render();$('#save-status').textContent='保存停止中・復旧が必要';}

function updateMusicUi(){const playing=player&&!player.audio.paused;const status=audioIds.has(music.settings.selectedId)?playing?'BGM ON':'BGM OFF':'曲を登録';const statusEl=$('#bgm-status');if(statusEl)statusEl.textContent=status;const hb=$('#header-bgm');if(hb)hb.textContent=status;for(const el of document.querySelectorAll('[data-music-status]'))el.textContent=status+' ／ 選曲・再生・停止・音量';const play=$('#music-play');if(play){play.disabled=!audioIds.has(music.settings.selectedId)||player?.loading;play.textContent=player?.loading?'読み込み中':playing?'停止':'再生';}const error=$('#music-error');if(error)error.textContent=player?.error||'';}
async function initMusic(){player?.dispose();try{music=await readMusic(db);audioIds=new Set(await readAudioIds(db));}catch(e){music={version:1,settings:musicDefaults(),tracks:[]};toast(e.message);}player=new MusicPlayer({settings:music.settings,load:id=>readAudio(db,id),onChange:updateMusicUi});updateMusicUi();}
function musicForm(){modal('BGM / 音楽室',`<p>起動時はオフ。選んだ曲だけを手動操作で読み込みます。</p><div id="music-error" role="status" class="red">${esc(player?.error||'')}</div><label class="form-field">選択曲<select id="music-select"><option value="">曲を選択</option>${music.tracks.map(t=>`<option value="${esc(t.id)}" ${t.id===music.settings.selectedId?'selected':''}>${esc(t.name)}${audioIds.has(t.id)?'':'（音源未登録）'}</option>`).join('')}</select></label>${music.settings.selectedId&&!audioIds.has(music.settings.selectedId)?'<p class="warning">選択曲の音源がありません。曲を登録し直してください。</p>':''}<div class="music-controls"><button class="primary" id="music-play" ${music.tracks.length?'':'disabled'}>再生</button><label>音量 <input id="music-volume" type="range" min="0" max="1" step="0.01" value="${music.settings.volume}"></label><label><input id="music-loop" type="checkbox" ${music.settings.loop?'checked':''}>リピート</label></div><label class="upload">${audioIds.size?'曲を追加・再登録':'曲を登録'}<input id="music-file" type="file" accept="audio/mpeg,audio/mp4,audio/wav,audio/ogg,audio/flac,audio/aac,audio/webm,.mp3,.m4a,.wav,.ogg,.flac,.aac,.webm"></label><p class="small-note">ご自身が利用できるSUNO等の音源を選択。1曲20MB・合計100MB・30曲まで。音源はこのブラウザに保存します。未対応形式・再生失敗でも管理機能は使えます。バックグラウンド再生は保証しません。管理画面全体の圏外起動は未対応です。</p>`);updateMusicUi();}
function backupForm(){modal('全体バックアップ',`<p>実務・計画・独立デモ・メモ・Excel原本・BGM設定を保存します。引継ぎ済みの現場・写真・予定・不具合・添付も含みます。旧保存キーは変更しません。</p><label class="backup-audio"><input id="include-audio" type="checkbox">音源ファイルも含める（${music.tracks.length}曲・登録容量 ${(music.tracks.reduce((n,t)=>n+t.size,0)/1048576).toFixed(1)}MB）</label><p class="small-note">含めない場合、別端末では音源の再登録が必要です。</p><button id="download-backup" class="primary">JSONを書き出す</button>`);}
async function persistMusic(){music.settings={...player.settings};await saveMusic(db,music);updateMusicUi();}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(['bgm-button','header-bgm'].includes(button?.id))musicForm();if(button?.id==='music-play'){if(player&&!player.audio.paused){player.stop();return;}act(async()=>{if(!player)throw Error('音楽室を利用できません');await player.play();},button);}});
document.addEventListener('input',e=>{if(e.target.id==='music-volume')player?.setVolume(e.target.value);});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='music-select'){player?.select(el.value);await act(persistMusic);}if(el.id==='music-volume')await act(persistMusic);if(el.id==='music-loop'){player?.setLoop(el.checked);await act(persistMusic);}if(el.id==='music-file'){const f=el.files?.[0];if(!f||musicBusy)return;musicBusy=true;await act(async()=>{if(!db||blocked)throw Error('保存領域を利用できません');if(f.size===0||f.size>20*1024*1024)throw Error('音源は1曲20MB以下で選択してください');if(music.tracks.length>=30||music.tracks.reduce((n,t)=>n+t.size,0)+f.size>100*1024*1024)throw Error('音源の登録上限（30曲・合計100MB）に達しました');const ext=f.name.split('.').pop().toLowerCase(),type=({mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',ogg:'audio/ogg',flac:'audio/flac',aac:'audio/aac',webm:'audio/webm'})[ext];if(!type)throw Error('mp3・m4a・wav・ogg・flac・aac・webmの音源を選択してください');const bytes=await f.arrayBuffer(),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');const duplicate=music.tracks.find(t=>t.hash===hash);if(duplicate){await saveMusic(db,music,{id:duplicate.id,blob:new Blob([bytes],{type})});audioIds.add(duplicate.id);player.select(duplicate.id);await persistMusic();musicForm();toast('登録済みの曲を選択しました。音源を再保存しました');return;}const t={id:uid(),name:f.name.slice(0,300),type,size:f.size,hash},next={version:1,tracks:[...music.tracks,t],settings:{...player.settings,selectedId:t.id}};await saveMusic(db,next,{id:t.id,blob:new Blob([bytes],{type})});music=next;audioIds.add(t.id);player.select(t.id);musicForm();toast('曲を登録しました。再生ボタンで開始します');});musicBusy=false;}});

let entityDirty=false;document.addEventListener('input',e=>{if(e.target.closest('#entity-form'))entityDirty=true;});document.querySelector('#dialog').addEventListener('close',()=>entityDirty=false);document.querySelector('#dialog').addEventListener('cancel',e=>{if(entityDirty&&!confirm('未保存の入力があります。閉じますか？'))e.preventDefault();});document.addEventListener('click',e=>{if(entityDirty&&e.target.closest('#close-dialog,button[data-page]')&&!confirm('未保存の入力があります。閉じますか？')){e.stopImmediatePropagation();e.preventDefault();}},true);

const requestedPage=new URLSearchParams(location.search).get('page');if(['home','map','inspections','others','calendar'].includes(requestedPage))go(requestedPage);
